/* Scatter 46 RX channels (lane-major packed) */
.global _scatter_chip1;
_scatter_chip1:
#if DSP4_BLOCK_KERNELS
    rts;
#endif
    /* r0 = sample index (0..31) */
    r6 = dm(_rx_active_buf);
    i1 = _c1_rx_off;
    i2 = _c1_rx_stride;
    i3 = _c1_rx_slot_ptrs;
    r7 = 46;
    lcntr = r7; do .scatter_chip1_lp until lce;
        r3 = dm(i1, 1);       /* off */
        r4 = dm(i2, 1);       /* stride */
        r2 = r0 * r4 (SSI);   /* sample*stride */
        r3 = r3 + r2;
        r3 = r6 + r3;         /* DMA word address */
        r5 = dm(i3, 1);       /* node slot var ptr */
        #if DSP4_BLOCK_KERNELS
        r5 = r5 + r0;         /* slot[sample] */
        #endif
        i4 = r3;
        r2 = dm(i4, 0);   /* read DMA */
        r2 = ashift r2 by -3;  /* Q1.31 -> Q4.28 */
        i4 = r5;
        dm(i4, 0) = r2;   /* write slot var */
    .scatter_chip1_lp:
        nop;
    rts;
_scatter_chip1.end:

/* Peak-hold meter scan over RX inputs (once per block) */
.global _meter_scan_chip1;
_meter_scan_chip1:
    i0 = _c1_rx_slot_ptrs;
    i1 = _meter_peaks;
    m0 = 0;
    m1 = 1;
    r5 = 46;
    lcntr = r5; do .meter_scan_chip1_lp until lce;
        r2 = dm(i0, 1);
        i2 = r2;
        r3 = dm(i2, 0);   /* Q4.28 sample */
        r3 = abs r3;
        r4 = -28;
        f3 = float r3 by r4;  /* peaks stay FLOAT (readback contract) */
        f4 = dm(i1, m0);
        comp(f3, f4);
        if gt f4 = f3;
        dm(i1, m1) = f4;
    .meter_scan_chip1_lp:
        nop;
    rts;
_meter_scan_chip1.end:

/* Gather 37 inter-chip sends (lane-major packed) */
.global _gather_chip1;
_gather_chip1:
    /* r0 = sample index (0..31) */
    r6 = dm(_ic_tx_active_buf);
    i1 = _c1_ic_tx_off;
    i2 = _c1_ic_tx_stride;
    i3 = _c1_ic_tx_ptrs;
    r7 = 37;
    lcntr = r7; do .gather_chip1_lp until lce;
        r3 = dm(i1, 1);       /* off */
        r4 = dm(i2, 1);       /* stride */
        r2 = r0 * r4 (SSI);   /* sample*stride */
        r3 = r3 + r2;
        r3 = r6 + r3;         /* DMA word address */
        r5 = dm(i3, 1);       /* node slot var ptr */
        #if DSP4_BLOCK_KERNELS
        r5 = r5 + r0;         /* slot[sample] */
        #endif
        i4 = r5;
        r2 = dm(i4, 0);   /* read slot var */
        i4 = r3;
        dm(i4, 0) = r2;   /* write DMA */
    .gather_chip1_lp:
        nop;
    rts;
_gather_chip1.end:

/* Apply boot-time input patch: ptrs[i] = defaults[patch[i]] */
.global _rx_patch_apply;
_rx_patch_apply:
    i0 = _rx_patch_regs;
    i1 = _c1_rx_slot_ptrs;
    r5 = 46;
    r6 = 45;          /* clamp bound */
#if DSP4_BLOCK_KERNELS
    r7 = 0;               /* running entry index for the inverse */
#endif
    lcntr = r5; do .c1_rxpatch until lce;
        r2 = dm(i0, 1);       /* patch index */
        comp(r2, r6);
        if gt r2 = r6;        /* clamp out-of-range index */
        r3 = 0;
        comp(r2, r3);
        if lt r2 = r3;
        i2 = _c1_rx_slot_defaults;
        m1 = r2;
        modify(i2, m1);
        r3 = dm(i2, 0);       /* default ptr at patch index */
        dm(i1, 1) = r3;
#if DSP4_BLOCK_KERNELS
        /* node_entry[patch[i]] = i -- the inverse kernels need */
        i2 = _c1_rx_node_entry;
        m1 = r2;
        modify(i2, m1);
        dm(i2, 0) = r7;
        r7 = r7 + 1;
#endif
    .c1_rxpatch:
        nop;
    rts;
_rx_patch_apply.end:
